/* --- Shiki Dual Theme Syntax Highlighting --- */
pre.shiki {
  background-color: transparent !important;
  margin: 0;
  padding: 0;
  overflow-x: auto;
}

pre.shiki code {
  display: block;
  width: fit-content;
  min-width: 100%;
  font-family: var(--font-mono);
}

html.dark .shiki,
html.dark .shiki span {
  color: var(--shiki-dark) !important;
  background-color: transparent !important;
  font-style: var(--shiki-dark-font-style) !important;
  font-weight: var(--shiki-dark-font-weight) !important;
  text-decoration: var(--shiki-dark-text-decoration) !important;
}

html:not(.dark) .shiki,
html:not(.dark) .shiki span {
  color: var(--shiki-light) !important;
  background-color: transparent !important;
  font-style: var(--shiki-light-font-style) !important;
  font-weight: var(--shiki-light-font-weight) !important;
  text-decoration: var(--shiki-light-text-decoration) !important;
}

/* --- CLI Command Syntax Highlighting (Bash Token Overrides) --- */
.language-bash .token.function,
.language-bash .token.builtin {
  color: #10b981 !important; /* Green for bunx, npx, pnpm, yarn */
  font-weight: 600;
}

.language-bash .token.package,
.language-bash .token.string {
  color: var(--primary) !important; /* Nikala UI Brand Accent Color */
}

/* Fallback span styling for CLI commands */
.cli-runner {
  color: #10b981;
  font-weight: 600;
}

.cli-package {
  color: var(--primary);
  font-weight: 600;
}

/* --- Modern Custom Scrollbar (Nikala UI Design System) --- */
@layer base {
  /* Firefox & W3C Standard */
  * {
    scrollbar-width: thin;
    scrollbar-color: var(--border) transparent;
  }

  /* WebKit (Chrome, Edge, Safari, Brave, Opera) */
  ::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }

  ::-webkit-scrollbar-track {
    background: transparent;
  }

  ::-webkit-scrollbar-thumb {
    background: var(--border);
    border-radius: 9999px;
    transition: background-color 0.2s ease;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: var(--muted-foreground);
  }

  ::-webkit-scrollbar-corner {
    background: transparent;
  }
}

/* Hide scrollbar utility */
.no-scrollbar::-webkit-scrollbar {
  display: none;
}
.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

